// Checkout conversion fix: ensure paidEvents increments on successful payment
const { logEvent } = require('./logger');

module.exports = function checkoutConversionFix(req, res, next) {
  const originalJson = res.json.bind(res);
  res.json = function (body) {
    if (res.statusCode === 200 && body && body.success) {
      // Increment paidEvents via revenue module
      const revenue = require('./revenue');
      revenue.recordPaidEvent({ amount: body.amount || 0, currency: 'USD' });
      logEvent('checkout_conversion', { status: 'success' });
    }
    return originalJson(body);
  };
  next();
};
